CREATE DATABASE IF NOT EXISTS schema CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE schema;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','manager','lawyer','client') NOT NULL DEFAULT 'client',education_level VARCHAR(120),location VARCHAR(150),contacts VARCHAR(80),gender VARCHAR(30),failed_attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,locked_until DATETIME NULL,last_login DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cases(id INT AUTO_INCREMENT PRIMARY KEY,client_id INT NOT NULL,lawyer_id INT NULL,title VARCHAR(200) NOT NULL,description TEXT NOT NULL,category VARCHAR(100) NOT NULL,status ENUM('submitted','under_review','assigned','in_progress','closed','rejected') DEFAULT 'submitted',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES users(id),FOREIGN KEY(lawyer_id) REFERENCES users(id));
CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,client_id INT NOT NULL,lawyer_id INT NOT NULL,appointment_at DATETIME NOT NULL,notes TEXT,status ENUM('requested','approved','completed','cancelled') DEFAULT 'requested',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES users(id),FOREIGN KEY(lawyer_id) REFERENCES users(id));
CREATE TABLE files(id INT AUTO_INCREMENT PRIMARY KEY,case_id INT NOT NULL,uploader_id INT NOT NULL,original_name VARCHAR(255),storage_name VARCHAR(255) UNIQUE, mime_type VARCHAR(100),size_bytes INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(case_id) REFERENCES cases(id),FOREIGN KEY(uploader_id) REFERENCES users(id));
CREATE TABLE password_resets(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NOT NULL,used TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(100),entity_type VARCHAR(50),entity_id INT NULL,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
